import { Context, Effect, Layer } from 'effect'
import { RuntimeError } from '@hrbr/runtime-core'
import { isRuntimeSecretRefHandle, runtimeSecretRefId } from '@hrbr/runtime-provider-secrets'

export type RuntimeSandArgvPart =
  | { readonly kind: 'literal'; readonly value: string }
  | { readonly kind: 'input'; readonly path: string }
  | {
      readonly kind: 'option'
      readonly path: string
      readonly flag: string
      readonly omit_if_empty?: boolean | undefined
    }
  | { readonly kind: 'flag'; readonly path: string; readonly flag: string }

export interface RuntimeSandCommandBinding {
  readonly argv_template: ReadonlyArray<RuntimeSandArgvPart>
  readonly sand_stdin_mode: 'none' | 'json' | 'text'
  readonly sand_result_mode: string
  readonly timeout_ms?: number | undefined
  readonly tool_name?: string | undefined
}

export interface RuntimeSandSourceConfig {
  readonly cwd_policy?: string | undefined
  readonly cwd?: string | undefined
  readonly args?: ReadonlyArray<string> | undefined
}

export interface RuntimeSandCallOptions {
  readonly env?: Record<string, string> | undefined
  readonly secret_env?: Record<string, string> | undefined
  readonly cwd?: string | undefined
  readonly timeout_ms?: number | undefined
}

export interface RuntimeSandInvocationInput {
  readonly namespace: string
  readonly toolName: string
  readonly resultMode: string
  readonly invoke: () => Promise<unknown>
}

export interface RuntimeSandInvocationResult {
  readonly raw: unknown
  readonly value: unknown
}

export interface RuntimeSandProvider {
  readonly invoke: (
    input: RuntimeSandInvocationInput
  ) => Effect.Effect<RuntimeSandInvocationResult, RuntimeError>
}

export const RuntimeSandProvider = Context.Service<RuntimeSandProvider>(
  '@hrbr/runtime-provider-sand/RuntimeSandProvider'
)

export const RuntimeSandProviderLive = Layer.succeed(RuntimeSandProvider, {
  invoke: (input) =>
    Effect.tryPromise({
      try: async () => {
        const raw = await input.invoke()
        return { raw, value: normalizeRuntimeSandResult(raw, input.resultMode) }
      },
      catch: (cause) =>
        new RuntimeError('provider', 'Sand provider invocation failed', {
          namespace: input.namespace,
          toolName: input.toolName,
          cause,
        }),
    }),
})

export function readRuntimeInputPath(input: Record<string, unknown>, path: string): unknown {
  let current: unknown = input
  for (const segment of path.split('.').filter(Boolean)) {
    if (!current || typeof current !== 'object') return undefined
    current = (current as Record<string, unknown>)[segment]
  }
  return current
}

export function toRuntimeCliString(value: unknown): string | null {
  if (value === null || value === undefined) return null
  if (typeof value === 'string') return value
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value)
  }
  try {
    return JSON.stringify(value)
  } catch {
    return String(value)
  }
}

export function normalizeRuntimeStringRecord(value: unknown): Record<string, string> | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined
  const out: Record<string, string> = {}
  for (const [key, raw] of Object.entries(value as Record<string, unknown>)) {
    const str = toRuntimeCliString(raw)
    if (str !== null) out[key] = str
  }
  return Object.keys(out).length > 0 ? out : undefined
}

const SAND_ENV_KEY_RE = /^[A-Z][A-Z0-9_]*$/
const BLOCKED_SAND_ENV_KEYS = new Set([
  'PATH',
  'HOME',
  'PWD',
  'SHELL',
  'NODE_OPTIONS',
  'BUN_OPTIONS',
])

export function isBlockedRuntimeSandEnvKey(key: string): boolean {
  const normalized = key.trim().toUpperCase()
  return BLOCKED_SAND_ENV_KEYS.has(normalized) || normalized.startsWith('HRBR_')
}

export function normalizeRuntimeSandSecretEnvRecord(
  value: unknown
): Record<string, string> | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined
  const out: Record<string, string> = {}
  for (const [env, raw] of Object.entries(value as Record<string, unknown>)) {
    if (!SAND_ENV_KEY_RE.test(env)) {
      throw new Error(`sand secret_env key is invalid: ${env}`)
    }
    if (isBlockedRuntimeSandEnvKey(env)) {
      throw new Error(`sand secret_env key is blocked: ${env}`)
    }
    if (!isRuntimeSecretRefHandle(raw)) {
      throw new Error(`sand secret_env value must be a Harbor secret ref: ${env}`)
    }
    out[env] = runtimeSecretRefId(raw)
  }
  return Object.keys(out).length > 0 ? out : undefined
}

export function buildRuntimeSandCliArgv(
  binding: RuntimeSandCommandBinding,
  input: Record<string, unknown>
): string[] {
  const out: string[] = []
  for (const part of binding.argv_template) {
    switch (part.kind) {
      case 'literal':
        out.push(part.value)
        break
      case 'input': {
        const value = toRuntimeCliString(readRuntimeInputPath(input, part.path))
        if (value !== null) out.push(value)
        break
      }
      case 'option': {
        const rawValue = readRuntimeInputPath(input, part.path)
        const value = toRuntimeCliString(rawValue)
        if (value === null || value.length === 0) {
          if (!part.omit_if_empty) out.push(part.flag)
          break
        }
        out.push(part.flag, value)
        break
      }
      case 'flag': {
        const rawValue = readRuntimeInputPath(input, part.path)
        if (rawValue) out.push(part.flag)
        break
      }
    }
  }
  return out
}

export function resolveRuntimeSandCwd(
  sourceConfig: RuntimeSandSourceConfig,
  input: Record<string, unknown>,
  originCwd: string | undefined,
  overrideCwd: string | undefined,
  normalizeOriginCwd: (cwd: string | undefined) => string | undefined = (cwd) => cwd
): string | undefined {
  if (overrideCwd) {
    if (sourceConfig.cwd_policy !== 'call') {
      throw new Error('sand cwd override is not allowed for this source')
    }
    return overrideCwd
  }
  switch (sourceConfig.cwd_policy) {
    case 'workspace':
      return normalizeOriginCwd(originCwd)
    case 'configured':
      return typeof sourceConfig.cwd === 'string' && sourceConfig.cwd.length > 0
        ? sourceConfig.cwd
        : undefined
    case 'call': {
      const raw = readRuntimeInputPath(input, 'cwd')
      return typeof raw === 'string' && raw.length > 0 ? raw : undefined
    }
    default:
      return undefined
  }
}

export function resolveRuntimeSandStdin(
  binding: RuntimeSandCommandBinding,
  input: Record<string, unknown>
): string | undefined {
  switch (binding.sand_stdin_mode) {
    case 'none':
      return undefined
    case 'json':
      return JSON.stringify(input)
    case 'text': {
      const stdinText = readRuntimeInputPath(input, 'stdin_text')
      if (typeof stdinText === 'string') return stdinText
      const text = readRuntimeInputPath(input, 'text')
      if (typeof text === 'string') return text
      const value = toRuntimeCliString(input)
      return value ?? undefined
    }
  }
}

export function normalizeRuntimeSandCallOptions(
  input: unknown
): RuntimeSandCallOptions | undefined {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return undefined
  const raw = input as Record<string, unknown>
  const env = normalizeRuntimeStringRecord(raw.env)
  const secret_env = normalizeRuntimeSandSecretEnvRecord(raw.secret_env)
  const cwd = typeof raw.cwd === 'string' && raw.cwd.length > 0 ? raw.cwd : undefined
  const timeout_ms =
    typeof raw.timeout_ms === 'number' && Number.isFinite(raw.timeout_ms) && raw.timeout_ms > 0
      ? raw.timeout_ms
      : undefined
  if (!env && !secret_env && !cwd && timeout_ms === undefined) return undefined
  return {
    ...(env ? { env } : {}),
    ...(secret_env ? { secret_env } : {}),
    ...(cwd ? { cwd } : {}),
    ...(timeout_ms !== undefined ? { timeout_ms } : {}),
  }
}

export function normalizeRuntimeSandResult(raw: unknown, resultMode: string): unknown {
  if (!raw || typeof raw !== 'object') return raw
  const envelope = raw as Record<string, unknown>
  if (envelope.status === 'error' || envelope.status === 'cancelled') {
    const stderr =
      typeof envelope.stderr === 'string' && envelope.stderr.length > 0
        ? envelope.stderr
        : undefined
    const genericExitError =
      typeof envelope.error === 'string' && /^sand command exited with code\b/.test(envelope.error)
    const message =
      stderr && genericExitError
        ? stderr
        : typeof envelope.error === 'string' && envelope.error.length > 0
          ? envelope.error
          : stderr
            ? stderr
            : 'Sand invocation failed'
    throw new Error(message)
  }
  if (envelope.result !== undefined) return envelope.result
  if (resultMode === 'exit_code_only') return envelope.exit_code ?? null
  if (resultMode === 'binary_base64') return envelope.stdout ?? envelope

  const stdout = typeof envelope.stdout === 'string' ? envelope.stdout : ''
  if (resultMode === 'json_stdout' && stdout.length > 0) {
    try {
      return JSON.parse(stdout)
    } catch {
      return stdout
    }
  }
  if (stdout.length > 0) return stdout
  return envelope
}

export function sanitizeRuntimeSandInvocationLogInput(
  namespace: string,
  tool: string,
  input: Record<string, unknown>,
  options:
    | {
        env?: Record<string, string> | undefined
        cwd?: string | undefined
        timeout_ms?: number | undefined
      }
    | undefined,
  envKeys: ReadonlyArray<string>,
  secretEnvKeys: ReadonlyArray<string> = []
): Record<string, unknown> {
  return {
    namespace,
    tool,
    input,
    options: options
      ? {
          ...(options.cwd ? { cwd: options.cwd } : {}),
          ...(options.timeout_ms !== undefined ? { timeout_ms: options.timeout_ms } : {}),
          ...(envKeys.length > 0 ? { env_keys: envKeys } : {}),
          ...(secretEnvKeys.length > 0 ? { secret_env_keys: secretEnvKeys } : {}),
        }
      : undefined,
  }
}
